parameters.text:
=Extract structured client lead data from this submission:

Contact Name: {{$json.body.lead.name}}
Email: {{$json.body.lead.email}}
Organization: {{$json.body.lead.organization}}
Requirements: {{$json.body.lead.notes}}

Output JSON with: organization_name, organization_type (nonprofit/for_profit/charity), sector (community_services/arts_culture/health/etc), current_systems, candidate_needs (boolean flags for bookkeeping, payroll, financial_reporting, compliance, digital_transformation), payroll_headcount_estimate.

parameters.jsCode:
const lead = $input.first().json;
const body = $('Lead Webhook Ingress').first().json.body || {};
const rawLead = body.lead || {};

const clientName = lead.organization_name || rawLead.organization || 'Unspecified Organization';
const contactEmail = rawLead.email || lead.email || '';
const candidateNeeds = lead.candidate_needs || {};

const draftScope = {};
if (candidateNeeds.bookkeeping) {
  draftScope.bookkeeping = { cadence: 'monthly', ap_ar: true, reconciliations: true, catchup_cleanup: false };
}
if (candidateNeeds.payroll) {
  draftScope.payroll = { cadence: 'semi_monthly', headcount_employees: lead.payroll_headcount_estimate || 0, sympl_processes_payroll: true };
}
if (candidateNeeds.financial_reporting) {
  draftScope.financial_reporting = { cadence: 'monthly', board_package: true };
}

const isComplete = Boolean(clientName && contactEmail && Object.keys(draftScope).length > 0);

return {
  json: {
    client_name: clientName,
    contact_email: contactEmail,
    organization_type: lead.organization_type || 'nonprofit',
    sector: lead.sector || 'community_services',
    current_systems: lead.current_systems || [],
    draft_requested_scope: draftScope,
    is_intake_complete: isComplete
  }
};

const approval = $input.first().json.body || $input.first().json;
const dealData = $('Structured Schema Validator').first().json;

// Enforce mandatory scope firewall
const approvedScope = approval.approved_scope || {};
if (Object.keys(approvedScope).length === 0) {
  throw new Error('APPROVAL_REQUIRED: approved_scope cannot be empty before proposal generation.');
}

return {
  json: {
    client_id: `client_${approval.deal_id || 'demo'}`,
    organization: {
      name: dealData.client_name,
      organization_type: dealData.organization_type,
      sector: dealData.sector,
      description: approval.description || 'Verified via discovery call.',
      current_systems: dealData.current_systems,
      target_systems: approval.target_systems || ['QuickBooks Online']
    },
    engagement: {
      engagement_type: approval.engagement_type || 'recurring',
      complexity: approval.complexity || 'standard',
      diagnostic_focus: approval.diagnostic_focus || ['internal_controls']
    },
    requested_scope: dealData.draft_requested_scope || {},
    approved_scope: approvedScope,
    commercial_terms: {
      pricing_model: approval.pricing_model || 'fixed_retainer',
      currency: 'CAD',
      monthly_retainer: Number(approval.monthly_retainer) || null,
      setup_fee: Number(approval.setup_fee) || null,
      billing_schedule: 'monthly_in_advance',
      include_backlog_exclusion: true,
      software_fees_excluded: true
    },
    preferences: {
      include_why_us: approval.include_why_us !== false,
      is_competitive_pitch: Boolean(approval.is_competitive_pitch),
      is_trusted_continuity: Boolean(approval.is_trusted_continuity)
    }
  }
};
